// REPLACE THIS with a real Slack / email / Teams send node.
// The message MUST contain approveUrl and rejectUrl so the Wait node can
// pick up the decision (both resume the same execution, decision= tells which).
// $execution.resumeUrl already carries ?signature=..., so append with & not ?.
const current = $input.first().json;
const base = $execution.resumeUrl;
const sep = base.includes('?') ? '&' : '?';
return [{ json: { ...current, notified: true, approveUrl: `${base}${sep}decision=approve`, rejectUrl: `${base}${sep}decision=reject` } }];

// REPLACE WITH YOUR REAL DESTRUCTIVE ACTION (delete user, transfer funds, etc).
// This node only runs after explicit approve.
// After Wait resumes, the input is the approver's request, not the earlier
// items, so read correlationId from 'Stamp correlation'.
const correlationId = $('Stamp correlation').first().json.correlationId;
return [{ json: { ok: true, action: 'applied', correlationId } }];

// REPLACE with a real audit log writer.
// Input is the approver's request (or empty on wait timeout); correlationId
// lives in 'Stamp correlation'.
const req = $input.first().json;
const correlationId = $('Stamp correlation').first().json.correlationId;
return [{ json: { audit: 'rejected', approver: req.query?.approver ?? req.body?.approver ?? 'unknown', correlationId } }];
